import { useState } from 'react'
import { AppLayout } from '@/components/layout'
import { useAuthContext } from '@/hooks/AuthProvider'
import {
  setAccentColor,
  setTheme as applyThemePref,
  getAccentColor,
  getTheme,
  type ThemePref,
} from '@/hooks/useAccentColor'
import { saveAppearancePrefs } from '@/services/appearance'
import { toast } from '@/lib/toast'
import '../Settings.css'
import './AppearanceScreen.css'

export default function AppearanceScreen() {
  const { user } = useAuthContext()

  // Inicializa do perfil (banco) com fallback no cache local.
  const [theme, setThemeState] = useState<ThemePref>(user?.theme ?? getTheme())
  const [primaryColor, setPrimaryColor] = useState(user?.accent_color || getAccentColor())

  const pickColor = async (value: string) => {
    setPrimaryColor(value)
    setAccentColor(value) // aplica no site imediatamente
    try {
      await saveAppearancePrefs({ accentColor: value })
    } catch {
      toast('Erro ao salvar a cor', 'error')
    }
  }

  const pickTheme = async (value: ThemePref) => {
    setThemeState(value)
    applyThemePref(value)
    try {
      await saveAppearancePrefs({ theme: value })
    } catch {
      toast('Erro ao salvar o tema', 'error')
    }
  }

  const themes: { id: ThemePref; label: string; color: string }[] = [
    { id: 'light', label: 'Claro', color: '#ffffff' },
    { id: 'dark', label: 'Escuro', color: '#1a1a2e' },
    { id: 'system', label: 'Sistema', color: 'linear-gradient(135deg, #ffffff 50%, #1a1a2e 50%)' },
  ]

  const colors = [
    { id: 'blue', value: '#007aff', label: 'Azul' },
    { id: 'violet', value: '#8B5CF6', label: 'Violeta' },
    { id: 'green', value: '#34c759', label: 'Verde' },
    { id: 'orange', value: '#ff9500', label: 'Laranja' },
    { id: 'pink', value: '#ff2d55', label: 'Rosa' },
    { id: 'red', value: '#ff3b30', label: 'Vermelho' },
  ]

  return (
    <AppLayout title="Aparência" subtitle="Personalize o visual da interface">
      <div className="settings-page">
        <div className="settings-section">
          {/* Theme */}
          <div className="settings-card">
            <h3>Tema</h3>
            <p className="settings-description">Escolha o tema de cores da interface</p>
            <div className="theme-options">
              {themes.map(t => (
                <button
                  key={t.id}
                  className={`theme-option ${theme === t.id ? 'theme-option--active' : ''}`}
                  onClick={() => pickTheme(t.id)}
                >
                  <div className="theme-preview" style={{ background: t.color }} />
                  <span>{t.label}</span>
                </button>
              ))}
            </div>
            <p className="settings-hint">
              Sua preferência é salva na conta e segue você em qualquer dispositivo.
            </p>
          </div>

          {/* Primary Color */}
          <div className="settings-card">
            <h3>Cor Principal</h3>
            <p className="settings-description">Escolha a cor de destaque do sistema</p>
            <div className="color-options">
              {colors.map(c => (
                <button
                  key={c.id}
                  className={`color-option ${primaryColor.toLowerCase() === c.value.toLowerCase() ? 'color-option--active' : ''}`}
                  onClick={() => pickColor(c.value)}
                  title={c.label}
                >
                  <div className="color-preview" style={{ background: c.value }} />
                </button>
              ))}
            </div>
            <p className="settings-hint">
              Aplicada em todo o sistema — botões, links e o seu avatar.
            </p>
          </div>
        </div>
      </div>
    </AppLayout>
  )
}
