import { supabase } from '@/lib/supabase'

export type ThemePref = 'light' | 'dark' | 'system'

/**
 * Persiste as preferências de aparência do usuário logado via RPC
 * SECURITY DEFINER (update_appearance_prefs). Passar undefined mantém o
 * valor atual; accentColor = '' limpa a cor (volta ao padrão).
 */
export async function saveAppearancePrefs(prefs: {
  theme?: ThemePref
  accentColor?: string | null
}): Promise<void> {
  const { error } = await supabase.rpc('update_appearance_prefs', {
    p_theme: prefs.theme ?? undefined,
    p_accent_color: prefs.accentColor ?? undefined,
  })
  if (error) throw error
}
